    and COALESCE(p.del_flag, '0') = '0'
    
        and (
            p.product_name like concat('%', #{keyword}, '%')
            or p.product_code like concat('%', #{keyword}, '%')
            or p.product_pinyin like concat('%', #{keyword}, '%')
            or p.brand like concat('%', #{keyword}, '%')
            or p.search_keywords like concat('%', #{keyword}, '%')
        )
    
     and p.product_name like concat('%', #{productName}, '%')
     and p.product_pinyin like concat('%', #{productPinyin}, '%')
     and p.product_label like concat('%', #{productLabel}, '%')
     and p.product_code like concat('%', #{productCode}, '%')
     and p.product_local_code = #{productLocalCode}
     and p.category = #{category}
     and p.category_id = #{categoryId}
     and p.status = #{status}
     and p.unit = #{unit}
     and p.spec like concat('%', #{spec}, '%')
     and p.model like concat('%', #{model}, '%')
     and p.brand like concat('%', #{brand}, '%')
     and p.barcode = #{barcode}
     and p.producer like concat('%', #{producer}, '%')
     and p.inv_id = #{invId}
     and p.inv_name like concat('%', #{invName}, '%')
     and p.update_time >= #{updatedFrom}
     and p.update_time <= #{updatedTo}

order by p.update_time desc nulls last, p.create_time desc nulls last

